Python <pre><code>import polars as pl
import quantwave  # registers pl.col().ta

df = pl.DataFrame({
    "high":  [101, 102, 103, 102, 104],
    "low":   [99, 100, 101, 100, 102],
    "close": [100, 101, 102, 101, 103],
})

out = (
    df.lazy()
    .with_columns(
        pl.col("close").ta.rsi(timeperiod=14).alias("rsi"),
        pl.col("close").ta.supertrend("high", "low", period=10, multiplier=3.0).alias("st"),
    )
    .collect()
)
print(out.tail())
</code></pre> Rust (streaming) <pre><code>use quantwave_core::indicators::supertrend::SuperTrend;
